#!/usr/bin/env dotnet
// Generates this repo's Dockerfiles and manifest.yaml from versions.json and the Dockerfile templates.
// The repo owns these rules; ImageBuilder only reads the generated manifest.
//
// Usage: dotnet run generate.cs           Writes every generated file.
//        dotnet run generate.cs -- --test  Fails if any generated file is out of date.

#:package Fluid.Core@2.41.1
#:project ../ImageBuilder.Models/Microsoft.DotNet.ImageBuilder.Models.csproj
#:property PublishAot=false

using System.Text.Json.Nodes;
using Fluid;
using Microsoft.DotNet.ImageBuilder.Models.ManifestV2;

const string DotnetVersion = "10.0";

bool test = args.Contains("--test");
string root = AppContext.GetData("EntryPointFileDirectoryPath") as string
    ?? throw new InvalidOperationException("Run this file with 'dotnet run generate.cs'.");

JsonNode versions = JsonNode.Parse(File.ReadAllText(Path.Join(root, "versions.json")))
    ?? throw new InvalidDataException("versions.json must not be empty.");
JsonNode release = versions["dotnet"]?[DotnetVersion]
    ?? throw new InvalidDataException($"versions.json has no .NET {DotnetVersion} release.");

OS noble = new("noble", "Ubuntu 24.04", Libicu: "74", Libssl: "3t64");

Arch[] arches =
[
    new("linux/amd64", "amd64", "linux-x64"),
    new("linux/arm/v7", "arm32v7", "linux-arm"),
    new("linux/arm64/v8", "arm64v8", "linux-arm64"),
];

RepoRule[] repoRules =
[
    new("runtime-deps", "dotnet/runtime-deps", VersionProduct: "runtime", BaseRepo: null),
    new("runtime", "dotnet/runtime", VersionProduct: "runtime", BaseRepo: "runtime-deps"),
    new("aspnet", "dotnet/aspnet", VersionProduct: "aspnet", BaseRepo: "runtime"),
    new("sdk", "dotnet/sdk", VersionProduct: "sdk", BaseRepo: "aspnet"),
];

FluidParser parser = new();
TemplateOptions templateOptions = new() { StrictVariables = true, StrictFilters = true };

List<GeneratedFile> files = [];
Dictionary<string, Repo> repos = [];
foreach (RepoRule repoRule in repoRules)
{
    string version = release[repoRule.VersionProduct]?["productVersion"]?.GetValue<string>()
        ?? throw new InvalidDataException($"versions.json has no {repoRule.VersionProduct} productVersion.");
    string templatePath = $"Dockerfile.{repoRule.Key}.template";

    Dictionary<string, Platform> platforms = [];
    foreach (Arch arch in arches)
    {
        string dockerfilePath = $"src/{repoRule.Key}/{DotnetVersion}/{noble.Name}/{arch.Name}/Dockerfile";
        files.Add(new(dockerfilePath, RenderDockerfile(templatePath, noble, arch)));
        platforms[arch.Platform] = new Platform
        {
            DockerfilePath = dockerfilePath,
            BuildArgs = repoRule.BaseRepo is null ? [] : new() { ["REPO"] = $"$(Repo:{repoRule.BaseRepo})" },
            Tags = [$"{version}-{noble.Name}-{arch.Name}", $"{DotnetVersion}-{noble.Name}-{arch.Name}"],
        };
    }

    Image image = new()
    {
        SharedTags = [$"{version}-{noble.Name}", $"{DotnetVersion}-{noble.Name}", version, DotnetVersion],
        Platforms = platforms,
    };

    repos[repoRule.Key] = new Repo
    {
        Name = repoRule.Name,
        Images = new() { [$"{DotnetVersion}-{noble.Name}"] = image },
    };
}

Manifest manifest = new() { Registry = "mcr.microsoft.com", Repos = repos };
string manifestYaml = "# Generated by generate.cs. Do not edit.\n" + ManifestSerializer.Serialize(manifest);
files.Add(new("manifest.yaml", manifestYaml.ReplaceLineEndings("\n")));

return test ? CheckFiles() : WriteFiles();

string RenderDockerfile(string templatePath, OS os, Arch arch)
{
    string source = File.ReadAllText(Path.Join(root, templatePath));
    if (!parser.TryParse(source, out IFluidTemplate template, out string error))
    {
        throw new InvalidDataException($"{templatePath}: {error}");
    }

    TemplateContext context = new(templateOptions);
    context.SetValue("release", release);
    context.SetValue("os", new JsonObject
    {
        ["name"] = os.Name,
        ["displayName"] = os.DisplayName,
        ["libicu"] = os.Libicu,
        ["libssl"] = os.Libssl,
    });
    context.SetValue("arch", arch.Name);
    context.SetValue("rid", arch.Rid);
    // dotnet-docker installs arm32 noble images from Ubuntu 22.04's buildpack-deps image.
    context.SetValue("installerOs", os.Name == "noble" && arch.Name == "arm32v7" ? "jammy" : os.Name);
    return template.Render(context).ReplaceLineEndings("\n");
}

int WriteFiles()
{
    foreach (GeneratedFile file in files)
    {
        string fullPath = Path.Join(root, file.Path);
        Directory.CreateDirectory(Path.GetDirectoryName(fullPath) ?? root);
        File.WriteAllText(fullPath, file.Content);
    }

    Console.WriteLine($"Generated {files.Count} files");
    return 0;
}

int CheckFiles()
{
    // Git may check out files with CRLF line endings, so only compare the text.
    string[] outdated = [.. files
        .Where(file =>
        {
            string fullPath = Path.Join(root, file.Path);
            return !File.Exists(fullPath) || File.ReadAllText(fullPath).ReplaceLineEndings("\n") != file.Content;
        })
        .Select(file => file.Path)];

    foreach (string path in outdated)
    {
        Console.Error.WriteLine($"error: {path} is out of date. Run 'dotnet run generate.cs' to update it.");
    }

    Console.WriteLine($"Checked {files.Count} files");
    return outdated.Length == 0 ? 0 : 1;
}

// An OS the repo's images are based on, with the package versions its Dockerfiles install.
record OS(string Name, string DisplayName, string Libicu, string Libssl);

// An architecture: its OCI platform, its name in tags and paths, and the .NET RID of its downloads.
record Arch(string Platform, string Name, string Rid);

// A repo: its key, its published name, the product whose version it's tagged with,
// and the repo whose images it builds on.
record RepoRule(string Key, string Name, string VersionProduct, string? BaseRepo);

record GeneratedFile(string Path, string Content);
